17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.advice.CityAtCapacityException;
32	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitException;
33	import org.springframework.samples.petclinic.rest.advice.DuplicateIdentityException;
34	import org.springframework.samples.petclinic.rest.advice.FutureRegistrationDateException;
35	import org.springframework.samples.petclinic.rest.advice.InvalidAddressException;
36	import org.springframework.samples.petclinic.rest.advice.InvalidEmailException;
37	import org.springframework.samples.petclinic.rest.advice.InvalidPostcodeException;
38	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
39	import org.springframework.samples.petclinic.rest.api.OwnersApi;
40	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
41	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.PetDto;
43	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
46	import org.springframework.samples.petclinic.service.ClinicService;
47	import org.springframework.samples.petclinic.util.Households;
48	import org.springframework.samples.petclinic.util.Localities;
49	import org.springframework.security.access.prepost.PreAuthorize;
50	import org.springframework.web.bind.annotation.CrossOrigin;
51	import org.springframework.web.bind.annotation.RequestMapping;
52	import org.springframework.web.bind.annotation.RestController;
53	import org.springframework.web.util.UriComponentsBuilder;
54	
55	import jakarta.transaction.Transactional;
56	
57	/**
58	 * @author Vitaliy Fedoriv
59	 */
60	
61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    /**
67	     * Dedicated audit logger. On a successful owner create an audit line is emitted here carrying the
68	     * new owner's id, its assigned {@code customerCode}, its {@code registrationDate} and its
69	     * numeric {@code membershipLevel}.
70	     */
71	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
72	
73	    private final ClinicService clinicService;
74	
75	    private final OwnerMapper ownerMapper;
76	
77	    private final PetMapper petMapper;
78	
79	    private final VisitMapper visitMapper;
80	
81	    public OwnerRestControllerV1(ClinicService clinicService,
82	                                 OwnerMapper ownerMapper,
83	                                 PetMapper petMapper,
84	                                 VisitMapper visitMapper) {
85	        this.clinicService = clinicService;
86	        this.ownerMapper = ownerMapper;
87	        this.petMapper = petMapper;
88	        this.visitMapper = visitMapper;
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
94	        Collection<Owner> owners;
95	        if (lastName != null) {
96	            owners = this.clinicService.findOwnerByLastName(lastName);
97	        } else {
98	            owners = this.clinicService.findAllOwners();
99	        }
100	        if (owners.isEmpty()) {
101	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
102	        }
103	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
104	    }
105	
106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
109	        Owner owner = this.clinicService.findOwnerById(ownerId);
110	        if (owner == null) {
111	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
112	        }
113	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
119	        HttpHeaders headers = new HttpHeaders();
120	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
121	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
122	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
123	        rejectFutureRegistrationDate(registrationDate);
124	        if (registrationDate == null) {
125	            registrationDate = java.time.LocalDate.now();
126	        }
127	        registrationDate = toBusinessDay(registrationDate);
128	        owner.setRegistrationDate(registrationDate);
129	        rejectDailyLimitReached(registrationDate);
130	        rejectCityAtCapacity(owner.getCity());
131	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
132	        owner.setTelephone(telephone);
133	        String email = normalizeEmail(ownerFieldsDto.getEmail());
134	        owner.setEmail(email);
135	        owner.setPostcode(validatePostcode(owner.getCity(), ownerFieldsDto.getPostcode()));
136	        rejectDuplicateIdentity(owner);
137	        String region = Localities.region(owner.getPostcode(), owner.getCity());
138	        owner.setCustomerCode(assignCustomerCode(region, owner.getTelephone(), owner.getLastName()));
139	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
140	        owner.setBulkSignupWarning(computeBulkSignupWarning(registrationDate));
141	        owner.setHouseholdSize(countHouseholdMembers(owner.getLastName(), owner.getAddress()) + 1);
142	        Integer possibleDuplicateOf = findPossibleDuplicateOf(owner);
143	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
144	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
145	        this.clinicService.saveOwner(owner);
146	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
147	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
148	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
149	            ownerDto.getMembershipLevel());
150	        headers.setLocation(UriComponentsBuilder.newInstance()
151	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
152	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
153	    }
154	
155	    /**
156	     * Rejects creating an owner whose supplied {@code registrationDate} is later than the server
157	     * date (in the future). Only an explicitly supplied date is validated; a {@code null} date
158	     * (which later defaults to the server date) is accepted. The check is against the raw supplied
159	     * date, before any business-day adjustment.
160	     *
161	     * @param registrationDate the supplied registration date, or {@code null} when none was supplied
162	     * @throws FutureRegistrationDateException (400 Bad Request) if the supplied date is in the future
163	     */
164	    private void rejectFutureRegistrationDate(java.time.LocalDate registrationDate) {
165	        if (registrationDate != null && registrationDate.isAfter(java.time.LocalDate.now())) {
166	            throw new FutureRegistrationDateException(registrationDate);
167	        }
168	    }
169	
170	    /**
171	     * The maximum number of owners that may be created in a single day. Creating an owner once this
172	     * many owners already carry today's {@code registrationDate} is rejected.
173	     */
174	    private static final int DAILY_OWNER_LIMIT = 100;
175	
176	    /**
177	     * Rejects creating an owner once {@value #DAILY_OWNER_LIMIT} or more owners already carry the
178	     * given business day as their {@code registrationDate}. The count is keyed by the
179	     * business-day-adjusted registration date of the owner being created (see
180	     * {@link #toBusinessDay}), so all owners falling on the same business day count together. Owners
181	     * with no {@code registrationDate} are ignored.
182	     *
183	     * @param registrationDate the business-day-adjusted registration date of the owner being created
184	     * @throws DailyOwnerLimitException (429 Too Many Requests) if the daily limit is already reached
185	     */
186	    private void rejectDailyLimitReached(java.time.LocalDate registrationDate) {
187	        long count = this.clinicService.findAllOwners().stream()
188	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
189	            .count();
190	        if (count >= DAILY_OWNER_LIMIT) {
191	            throw new DailyOwnerLimitException(registrationDate);
192	        }
193	    }
194	
195	    /**
196	     * The threshold of owners already created on a business day beyond which a bulk-signup warning is
197	     * raised on a new owner. Once strictly more than this many owners already carry the day as their
198	     * {@code registrationDate}, the new owner's {@code bulkSignupWarning} is set to {@code true}.
199	     */
200	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
201	
202	    /**
203	     * Computes the {@code bulkSignupWarning} for an owner being created: {@code true} when more than
204	     * {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created today, otherwise
205	     * {@code false}. Existing owners are counted the same way the daily-limit rule counts them (see
206	     * {@link #rejectDailyLimitReached}), keyed by the business-day-adjusted registration date, and the
207	     * owner being created is excluded (it has not yet been saved).
208	     *
209	     * @param registrationDate the business-day-adjusted registration date of the owner being created
210	     * @return {@code true} if more than the threshold of owners already carry this business day
211	     */
212	    private boolean computeBulkSignupWarning(java.time.LocalDate registrationDate) {
213	        long count = this.clinicService.findAllOwners().stream()
214	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
215	            .count();
216	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
217	    }
218	
219	    /**
220	     * Rolls a registration date forward onto a business day: a Saturday or Sunday is moved forward to
221	     * the following Monday; a weekday is returned unchanged. This applies to the effective
222	     * registration date whether it was supplied in the request or defaulted to the server date, and
223	     * every value derived from the registration date uses the adjusted result.
224	     *
225	     * @param date the effective registration date
226	     * @return {@code date} itself when it is a weekday, otherwise the following Monday
227	     */
228	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
229	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
230	            || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY) {
231	            date = date.plusDays(1);
232	        }
233	        return date;
234	    }
235	
236	    /**
237	     * The maximum number of owners a single city may contain. Creating an owner in a city that
238	     * already holds this many owners is rejected.
239	     */
240	    private static final int CITY_CAPACITY = 50;
241	
242	    /**
243	     * Rejects creating an owner whose city already contains {@value #CITY_CAPACITY} or more owners.
244	     * Owners are counted per city comparing the city name case-insensitively (a {@code null} city is
245	     * treated as empty).
246	     *
247	     * @param city the city of the owner being created
248	     * @throws CityAtCapacityException (409 Conflict) if the city is already at capacity
249	     */
250	    private void rejectCityAtCapacity(String city) {
251	        String cityValue = city == null ? "" : city;
252	        long count = this.clinicService.findAllOwners().stream()
253	            .filter(existing -> cityValue.equalsIgnoreCase(
254	                existing.getCity() == null ? "" : existing.getCity()))
255	            .count();
256	        if (count >= CITY_CAPACITY) {
257	            throw new CityAtCapacityException(city);
258	        }
259	    }
260	
261	    /**
262	     * Assigns an owner's {@code customerCode} on create, formatted {@code '<REGION>-<HASH8>'} where
263	     * REGION is the owner's canonical region (derived by preferring the postcode, see
264	     * {@link Localities#region(String, String)} — the same region derivation shared with the
265	     * {@code locality}) and HASH8 is the first 8 upper-case hex characters of the SHA-256 digest of
266	     * the normalized (E.164) telephone concatenated with the last name (e.g. {@code 'NSW-3A7F9C2E'}).
267	     * There are no sequence numbers: the code is fully derived from the owner's own identity fields.
268	     *
269	     * @param region the owner's canonical region (the identity's REGION, shared with the locality)
270	     * @param telephone the owner's normalized (E.164) telephone
271	     * @param lastName the owner's last name
272	     * @return the assigned customer code
273	     */
274	    private String assignCustomerCode(String region, String telephone, String lastName) {
275	        String basis = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
276	        String hash8 = sha256UpperHex(basis).substring(0, 8);
277	        return region + "-" + hash8;
278	    }
279	
280	    /**
281	     * Returns the full upper-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
282	     */
283	    private static String sha256UpperHex(String value) {
284	        try {
285	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
286	                .digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));
287	            StringBuilder sb = new StringBuilder(digest.length * 2);
288	            for (byte b : digest) {
289	                sb.append(String.format("%02X", b));
290	            }
291	            return sb.toString();
292	        }
293	        catch (java.security.NoSuchAlgorithmException e) {
294	            throw new IllegalStateException("SHA-256 not available", e);
295	        }
296	    }
297	
298	    /**
299	     * Counts how many existing owners share the given first and last name, compared
300	     * case-insensitively, at the time this owner is created. The value excludes the owner
301	     * being created (which has not yet been saved) and is stored on the new owner and returned
302	     * as its {@code namesakeCount}.
303	     *
304	     * @param firstName the first name of the owner being created
305	     * @param lastName the last name of the owner being created
306	     * @return the number of existing owners with the same first and last name
307	     */
308	    private int countNamesakes(String firstName, String lastName) {
309	        String first = firstName == null ? "" : firstName;
310	        String last = lastName == null ? "" : lastName;
311	        return (int) this.clinicService.findAllOwners().stream()
312	            .filter(existing -> first.equalsIgnoreCase(existing.getFirstName())
313	                && last.equalsIgnoreCase(existing.getLastName()))
314	            .count();
315	    }
316	
317	    /**
318	     * Counts how many existing owners belong to the same household as the owner being created, i.e.
319	     * share its {@code householdId} (derived by {@link Households#householdId} from the normalized last
320	     * name and address). The value excludes the owner being created (which has not yet been saved), so
321	     * the household's size after this create is this count plus one. It is stored on the new owner.
322	     *
323	     * @param lastName the last name of the owner being created
324	     * @param address the normalized address of the owner being created
325	     * @return the number of existing owners sharing this owner's household
326	     */
327	    private int countHouseholdMembers(String lastName, String address) {
328	        String householdId = Households.householdId(lastName, address);
329	        return (int) this.clinicService.findAllOwners().stream()
330	            .filter(existing -> householdId.equals(
331	                Households.householdId(existing.getLastName(), existing.getAddress())))
332	            .count();
333	    }
334	
335	    /**
336	     * Finds the existing owner, if any, that the owner being created is a soft duplicate of: an owner
337	     * sharing this owner's last name (compared case-insensitively) and postcode (an exact match of the
338	     * stored 4-digit value) while carrying a <em>different</em> telephone. A soft match is distinct from
339	     * the hard duplicate rejected earlier by {@link #rejectDuplicateIdentity}: the owner is still
340	     * created, but flagged. When more than one existing owner matches, the earliest (lowest id) is
341	     * returned so the reference is deterministic. An owner with no postcode can never soft-match.
342	     *
343	     * @param owner the owner being created, with its telephone and postcode already normalized/validated
344	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
345	     */
346	    private Integer findPossibleDuplicateOf(Owner owner) {
347	        String postcode = owner.getPostcode();
348	        if (postcode == null) {
349	            return null;
350	        }
351	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
352	        String telephone = owner.getTelephone();
353	        return this.clinicService.findAllOwners().stream()
354	            .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName()))
355	            .filter(existing -> postcode.equals(existing.getPostcode()))
356	            .filter(existing -> !java.util.Objects.equals(telephone, existing.getTelephone()))
357	            .map(Owner::getId)
358	            .filter(java.util.Objects::nonNull)
359	            .min(java.util.Comparator.naturalOrder())
360	            .orElse(null);
361	    }
362	
363	    /**
364	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
365	     * stripped. A leading '+' and its country code are kept as given; otherwise country code '+61' is
366	     * assumed and a single leading '0' is dropped from the national digits. The resulting number must
367	     * have 8 to 15 digits after the '+'. For example {@code "0412 345 678"} becomes
368	     * {@code "+61412345678"}. The E.164 value is stored and returned.
369	     * <p>
370	     * The national-number length (the digits after the country code) is additionally validated for
371	     * country codes with a fixed length: '+61' requires exactly 9 national digits and '+1' requires
372	     * exactly 10. Numbers of other country codes are only bound by the overall 8-to-15-digit limit.
373	     *
374	     * @param telephone the raw telephone as submitted
375	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
376	     * @throws InvalidTelephoneException (400 Bad Request) if the value cannot form a valid E.164 number
377	     *         or its national-number length is wrong for its country code
378	     */
379	    private String normalizeTelephone(String telephone) {
380	        String raw = telephone == null ? "" : telephone.trim();
381	        boolean hasCountryCode = raw.startsWith("+");
382	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
383	        if (hasCountryCode) {
384	            cleaned = cleaned.substring(1);
385	        }
386	        String digits;
387	        if (hasCountryCode) {
388	            digits = cleaned;
389	        } else {
390	            if (cleaned.startsWith("0")) {
391	                cleaned = cleaned.substring(1);
392	            }
393	            digits = "61" + cleaned;
394	        }
395	        if (!digits.matches("[0-9]{8,15}") || !hasValidNationalLength(digits)) {
396	            throw new InvalidTelephoneException(telephone);
397	        }
398	        return "+" + digits;
399	    }
400	
401	    /**
402	     * Checks the national-number length of an E.164 digit string against its country code for the
403	     * country codes whose national number has a fixed length: '+61' requires 9 national digits and
404	     * '+1' requires 10. Any other country code passes, leaving it bound only by the overall length.
405	     *
406	     * @param digits the E.164 digits (the country code followed by the national number, without '+')
407	     * @return {@code true} if the national-number length is acceptable for the country code
408	     */
409	    private boolean hasValidNationalLength(String digits) {
410	        if (digits.startsWith("61")) {
411	            return digits.length() - 2 == 9;
412	        }
413	        if (digits.startsWith("1")) {
414	            return digits.length() - 1 == 10;
415	        }
416	        return true;
417	    }
418	
419	    /**
420	     * Syntactic email pattern: a non-empty local part, an '@', a domain with at least one dot and a
421	     * multi-character top-level label. Deliberately lenient about the exact character set while still
422	     * rejecting values that are clearly not addresses (e.g. missing '@').
423	     */
424	    private static final java.util.regex.Pattern EMAIL_PATTERN =
425	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$");
426	
427	    /**
428	     * Normalizes an owner's email. Email is optional: a {@code null} or blank value is left as
429	     * {@code null} (no email). When present it must be a syntactically valid address; the value is
430	     * lower-cased before being stored and returned.
431	     *
432	     * @param email the raw email as submitted, may be {@code null}
433	     * @return the lower-cased email, or {@code null} when none was supplied
434	     * @throws InvalidEmailException (400 Bad Request) if a non-blank value is not a valid address
435	     */
436	    private String normalizeEmail(String email) {
437	        if (email == null || email.isBlank()) {
438	            return null;
439	        }
440	        String trimmed = email.trim();
441	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
442	            throw new InvalidEmailException(email);
443	        }
444	        return trimmed.toLowerCase(java.util.Locale.ROOT);
445	    }
446	
447	    /**
448	     * Fixed region-to-postcode-range table: a region's postcode must fall within its inclusive range
449	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city whose region is not listed here (see
450	     * {@link Localities#region}) accepts any 4-digit postcode.
451	     */
452	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
453	        "NSW", new int[] {2000, 2099},
454	        "VIC", new int[] {3000, 3099},
455	        "QLD", new int[] {4000, 4099});
456	
457	    /**
458	     * Validates an owner's postcode on create. The postcode is optional: a {@code null} or blank value
459	     * is left as {@code null} (no postcode) and accepted. When present it must be exactly 4 digits and,
460	     * for a city whose region is in the fixed {@link #REGION_POSTCODE_RANGES range table}, must fall
461	     * within that region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no
462	     * known region accepts any 4-digit postcode. The value is stored and returned exactly as supplied.
463	     *
464	     * @param city the owner's city, used to derive the region whose range constrains the postcode
465	     * @param postcode the raw postcode as submitted, may be {@code null}
466	     * @return the postcode when supplied, or {@code null} when none was supplied
467	     * @throws InvalidPostcodeException (400 Bad Request) if a supplied postcode is not 4 digits or is
468	     *         out of range for the city's region
469	     */
470	    private String validatePostcode(String city, String postcode) {
471	        if (postcode == null || postcode.isBlank()) {
472	            return null;
473	        }
474	        if (!postcode.matches("[0-9]{4}")) {
475	            throw new InvalidPostcodeException(postcode);
476	        }
477	        int[] range = REGION_POSTCODE_RANGES.get(Localities.region(city));
478	        if (range != null) {
479	            int value = Integer.parseInt(postcode);
480	            if (value < range[0] || value > range[1]) {
481	                throw new InvalidPostcodeException(postcode);
482	            }
483	        }
484	        return postcode;
485	    }
486	
487	    /**
488	     * Common street-type abbreviations expanded to their full word during address normalization.
489	     */
490	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS = java.util.Map.of(
491	        "ST", "STREET",
492	        "RD", "ROAD",
493	        "AVE", "AVENUE");
494	
495	    /**
496	     * Normalizes an owner's address on create. Surrounding whitespace is trimmed and internal runs of
497	     * whitespace collapse to a single space, the value is upper-cased and common street-type
498	     * abbreviations are expanded to their full word ({@code ST} to {@code STREET}, {@code RD} to
499	     * {@code ROAD}, {@code AVE} to {@code AVENUE}). For example {@code "  12  main  st "} becomes
500	     * {@code "12 MAIN STREET"}. The normalized value is stored and returned, and is also the form used
501	     * for every address comparison (household duplicate detection and the shared household id).
502	     *
503	     * @param address the raw address as submitted
504	     * @return the normalized address
505	     * @throws InvalidAddressException (400 Bad Request) if the address is blank after normalization
506	     */
507	    private String normalizeAddress(String address) {
508	        String collapsed = (address == null ? "" : address).trim().replaceAll("\\s+", " ");
509	        if (collapsed.isEmpty()) {
510	            throw new InvalidAddressException(address);
511	        }
512	        String[] tokens = collapsed.toUpperCase(java.util.Locale.ROOT).split(" ");
513	        StringBuilder normalized = new StringBuilder(collapsed.length());
514	        for (int i = 0; i < tokens.length; i++) {
515	            if (i > 0) {
516	                normalized.append(' ');
517	            }
518	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
519	        }
520	        return normalized.toString();
521	    }
522	
523	    /**
524	     * Rejects creating an owner whose identity duplicates an existing owner's. All duplicate detection
525	     * is consolidated here onto the identity-bearing part of the derived {@code identityKey}: two
526	     * owners are duplicates when they share the same normalized telephone and the same normalized email
527	     * (a {@code null} email compared as an empty segment). Existing telephones are re-normalized to
528	     * E.164 and existing emails lower-cased before comparison, so equivalent values submitted in
529	     * different formats (e.g. national {@code "0412 345 678"} and international {@code "+61 412 345 678"})
530	     * still match.
531	     * <p>
532	     * The {@code householdId} is deliberately not part of this comparison: a household is a shared
533	     * grouping, so two members of the same household with different telephones have different
534	     * identities and are both allowed. Only owners with the same telephone and email collide.
535	     *
536	     * @param owner the owner being created, with its telephone and email already normalized
537	     * @throws DuplicateIdentityException (409 Conflict) if another owner has the same identity
538	     */
539	    private void rejectDuplicateIdentity(Owner owner) {
540	        String identity = personalIdentity(owner.getTelephone(), owner.getEmail());
541	        boolean duplicate = this.clinicService.findAllOwners().stream()
542	            .anyMatch(existing -> identity.equals(
543	                personalIdentity(toE164OrNull(existing.getTelephone()), existing.getEmail())));
544	        if (duplicate) {
545	            String householdId = Households.householdId(owner.getLastName(), owner.getAddress());
546	            throw new DuplicateIdentityException(
547	                Households.identityKey(owner.getTelephone(), owner.getEmail(), householdId));
548	        }
549	    }
550	
551	    /**
552	     * Builds the identity-bearing prefix of the {@code identityKey} used for duplicate detection:
553	     * the normalized telephone and email joined with {@code '|'}, lower-casing the email (the form it
554	     * is stored in, see {@link #normalizeEmail}) so addresses differing only in letter case still match.
555	     */
556	    private String personalIdentity(String telephone, String email) {
557	        String normalizedEmail = email == null ? "" : email.toLowerCase(java.util.Locale.ROOT);
558	        return (telephone == null ? "" : telephone) + "|" + normalizedEmail;
559	    }
560	
561	    /**
562	     * Normalizes an existing owner's telephone to E.164 for duplicate comparison, returning
563	     * {@code null} instead of throwing when the stored value cannot form a valid E.164 number, or
564	     * when its national-number length does not match its country code.
565	     */
566	    private String toE164OrNull(String telephone) {
567	        try {
568	            return normalizeTelephone(telephone);
569	        } catch (InvalidTelephoneException e) {
570	            return null;
571	        }
572	    }
573	
574	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
575	    @Override
576	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
577	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
578	        if (currentOwner == null) {
579	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
580	        }
581	        currentOwner.setAddress(ownerFieldsDto.getAddress());
582	        currentOwner.setCity(ownerFieldsDto.getCity());
583	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
584	        currentOwner.setLastName(ownerFieldsDto.getLastName());
585	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
586	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
587	        this.clinicService.saveOwner(currentOwner);
588	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
589	    }
590	
591	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
592	    @Transactional
593	    @Override
594	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
595	        Owner owner = this.clinicService.findOwnerById(ownerId);
596	        if (owner == null) {
597	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
598	        }
599	        this.clinicService.deleteOwner(owner);
600	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
601	    }
602	
603	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
604	    @Override
605	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
606	        Owner owner = this.clinicService.findOwnerById(ownerId);
607	        if (owner == null) {
608	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
609	        }
610	        HttpHeaders headers = new HttpHeaders();
611	        Pet pet = petMapper.toPet(petFieldsDto);
612	        owner.setId(ownerId);
613	        pet.setOwner(owner);
614	        pet.getType().setName(null);
615	        this.clinicService.savePet(pet);
616	        PetDto petDto = petMapper.toPetDto(pet);
617	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
618	            .buildAndExpand(pet.getId()).toUri());
619	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
620	    }
621	
622	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
623	    @Override
624	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
625	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
626	        if (currentOwner != null) {
627	            Pet currentPet = this.clinicService.findPetById(petId);
628	            if (currentPet != null) {
629	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
630	                currentPet.setName(petFieldsDto.getName());
631	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
632	                this.clinicService.savePet(currentPet);
633	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
634	            }
635	        }
636	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
637	    }
638	
639	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
640	    @Override
641	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
642	        HttpHeaders headers = new HttpHeaders();
643	        Visit visit = visitMapper.toVisit(visitFieldsDto);
644	        Pet pet = new Pet();
645	        pet.setId(petId);
646	        visit.setPet(pet);
647	        this.clinicService.saveVisit(visit);
648	        VisitDto visitDto = visitMapper.toVisitDto(visit);
649	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
650	            .buildAndExpand(visit.getId()).toUri());
651	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
652	    }
653	
654	
655	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
656	    @Override
657	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
658	        Owner owner = this.clinicService.findOwnerById(ownerId);
659	        if (owner != null) {
660	            Pet pet = owner.getPet(petId);
661	            if (pet != null) {
662	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
663	            }
664	        }
665	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
666	    }
667	}
